'use strict';
/**
 * Aura Needs — Your World, Your AI.
 * Secure backend: auth, chat history, real AI API proxy (streaming), admin control.
 * Zero npm dependencies. Requires Node.js 18+.
 */
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { promisify } = require('util');
const scrypt = promisify(crypto.scrypt);

// ---------------------------------------------------------------- .env loader
(function loadEnv() {
  try {
    const txt = fs.readFileSync(path.join(__dirname, '.env'), 'utf8');
    for (const line of txt.split(/\r?\n/)) {
      if (/^\s*#/.test(line)) continue;
      const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/);
      if (!m) continue;
      let v = m[2];
      if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
      if (process.env[m[1]] === undefined) process.env[m[1]] = v;
    }
  } catch (e) { /* no .env file — fine on hosting platforms */ }
})();

// -------------------------------------------------------------------- config
const PORT = Number(process.env.PORT) || 3000;
const DATA_DIR = process.env.DATA_DIR ? path.resolve(process.env.DATA_DIR) : path.join(__dirname, 'data');
const PUBLIC_DIR = path.join(__dirname, 'public');
const DB_FILE = path.join(DATA_DIR, 'db.json');
fs.mkdirSync(DATA_DIR, { recursive: true });

function loadSecret() {
  if (process.env.SESSION_SECRET && process.env.SESSION_SECRET.length >= 16) return process.env.SESSION_SECRET;
  const f = path.join(DATA_DIR, 'secret.key');
  try { return fs.readFileSync(f, 'utf8').trim(); } catch (e) { /* create */ }
  const s = crypto.randomBytes(48).toString('hex');
  try { fs.writeFileSync(f, s, { mode: 0o600 }); } catch (e) { /* ignore */ }
  return s;
}
const SECRET = loadSecret();

const PROVIDERS = {
  gemini:     { label: 'Google Gemini',          kind: 'openai',    baseUrl: 'https://generativelanguage.googleapis.com/v1beta/openai', model: 'gemini-2.5-flash' },
  openai:     { label: 'OpenAI',                 kind: 'openai',    baseUrl: 'https://api.openai.com/v1', model: 'gpt-4o-mini' },
  anthropic:  { label: 'Anthropic Claude',       kind: 'anthropic', baseUrl: 'https://api.anthropic.com', model: 'claude-sonnet-5-5' },
  groq:       { label: 'Groq',                   kind: 'openai',    baseUrl: 'https://api.groq.com/openai/v1', model: 'llama-3.3-70b-versatile' },
  openrouter: { label: 'OpenRouter',             kind: 'openai',    baseUrl: 'https://openrouter.ai/api/v1', model: 'openai/gpt-4o-mini' },
  custom:     { label: 'Custom (OpenAI-compatible)', kind: 'openai', baseUrl: '', model: '' },
};

const DEFAULT_SYSTEM = `You are Aura Needs AI — the assistant of the "Aura Needs" website (tagline: "Your World, Your AI."). You are a friendly, knowledgeable, general-purpose assistant, similar to ChatGPT or Gemini.
- Always reply in the language the user writes in. Bengali (বাংলা) and English are both fully supported; if the user mixes them, follow the main language of their message.
- Answer any question: general knowledge, math (show clear steps), science and technology, study help, stories and poems, Facebook captions, YouTube descriptions, website and app coding, analysis of images and files, and detailed explanations.
- Use Markdown: short paragraphs, lists, tables when useful, and fenced code blocks with the language name for any code.
- Be accurate and honest. If you are not sure, say so instead of guessing. Use the earlier context of this conversation.
- Your name is Aura Needs AI. If asked about the underlying model or company technology, say you are Aura Needs AI and that you do not have details about the technology behind you.`;

// ------------------------------------------------------------------ database
let db = { users: {}, chats: {}, settings: {}, stats: {} };
try {
  const raw = fs.readFileSync(DB_FILE, 'utf8');
  try {
    db = Object.assign(db, JSON.parse(raw));
  } catch (e) {
    const bak = DB_FILE + '.corrupt-' + Date.now();
    fs.renameSync(DB_FILE, bak);
    console.error('db.json was unreadable; moved to', bak);
  }
} catch (e) { /* first run */ }

let saveTimer = null;
function saveSoon() {
  if (saveTimer) return;
  saveTimer = setTimeout(() => { saveTimer = null; saveNow(); }, 400);
}
function saveNow() {
  try {
    const tmp = DB_FILE + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(db));
    fs.renameSync(tmp, DB_FILE);
  } catch (e) { console.error('Could not save database:', e.message); }
}
for (const sig of ['SIGINT', 'SIGTERM']) process.on(sig, () => { saveNow(); process.exit(0); });

// ------------------------------------------------------------------- helpers
const uid = () => crypto.randomUUID();
const now = () => Date.now();
const dayKey = () => new Date().toISOString().slice(0, 10);

function json(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(body);
}
class HttpError extends Error { constructor(status, code) { super(code); this.status = status; this.code = code; } }
class AIError extends Error { constructor(code, detail) { super(code); this.code = code; this.detail = detail || ''; } }

function readJson(req, limit = 100 * 1024) {
  return new Promise((resolve, reject) => {
    let size = 0; const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) { reject(new HttpError(413, 'too_large')); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      if (!chunks.length) return resolve({});
      try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8'))); } catch (e) { reject(new HttpError(400, 'bad_json')); }
    });
    req.on('error', reject);
  });
}

const buckets = new Map();
function hit(key, limit, windowMs) {
  const t = now();
  const arr = (buckets.get(key) || []).filter((x) => t - x < windowMs);
  if (arr.length >= limit) { buckets.set(key, arr); return false; }
  arr.push(t); buckets.set(key, arr); return true;
}
setInterval(() => { const t = now(); for (const [k, v] of buckets) if (!v.some((x) => t - x < 900000)) buckets.delete(k); }, 600000).unref();

function clientIp(req) {
  const xf = req.headers['x-forwarded-for'];
  if (xf) return String(xf).split(',')[0].trim();
  return req.socket.remoteAddress || 'unknown';
}

// ------------------------------------------------------------- auth / tokens
async function hashPassword(pw, salt) {
  return (await scrypt(pw, salt, 64)).toString('hex');
}
async function verifyPassword(pw, user) {
  const h = Buffer.from(await hashPassword(pw, user.salt), 'hex');
  const x = Buffer.from(user.hash, 'hex');
  return h.length === x.length && crypto.timingSafeEqual(h, x);
}
function signToken(payload) {
  const b = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const sig = crypto.createHmac('sha256', SECRET).update(b).digest('base64url');
  return b + '.' + sig;
}
function verifyToken(t) {
  if (typeof t !== 'string') return null;
  const [b, sig] = t.split('.');
  if (!b || !sig) return null;
  const good = crypto.createHmac('sha256', SECRET).update(b).digest('base64url');
  const a = Buffer.from(sig); const c = Buffer.from(good);
  if (a.length !== c.length || !crypto.timingSafeEqual(a, c)) return null;
  try {
    const p = JSON.parse(Buffer.from(b, 'base64url').toString('utf8'));
    if (!p.exp || p.exp < now()) return null;
    return p;
  } catch (e) { return null; }
}
function publicUser(u) { return { id: u.id, name: u.name, email: u.email, role: u.role }; }
function authUser(req) {
  const h = req.headers.authorization || '';
  const m = h.match(/^Bearer\s+(.+)$/i);
  if (!m) throw new HttpError(401, 'unauthorized');
  const p = verifyToken(m[1]);
  const u = p && db.users[p.uid];
  if (!u) throw new HttpError(401, 'unauthorized');
  if (u.banned) throw new HttpError(403, 'banned');
  return u;
}
function requireAdmin(req) {
  const u = authUser(req);
  if (u.role !== 'admin') throw new HttpError(403, 'forbidden');
  return u;
}
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

async function ensureAdmin() {
  const email = (process.env.ADMIN_EMAIL || '').trim().toLowerCase();
  const pw = process.env.ADMIN_PASSWORD || '';
  if (!email || !pw) {
    console.warn('[Aura Needs] ADMIN_EMAIL / ADMIN_PASSWORD are not set — no admin account will exist. Set them in your environment variables.');
    return;
  }
  if (!EMAIL_RE.test(email) || pw.length < 6) {
    console.warn('[Aura Needs] ADMIN_EMAIL must be a valid email and ADMIN_PASSWORD at least 6 characters.');
    return;
  }
  let u = Object.values(db.users).find((x) => x.email === email);
  if (!u) {
    const salt = crypto.randomBytes(16).toString('hex');
    u = { id: uid(), name: 'Admin', email, salt, hash: await hashPassword(pw, salt), role: 'admin', banned: false, createdAt: now(), lastLogin: 0 };
    db.users[u.id] = u;
  } else {
    u.role = 'admin'; u.banned = false;
    if (!(await verifyPassword(pw, u))) {
      u.salt = crypto.randomBytes(16).toString('hex');
      u.hash = await hashPassword(pw, u.salt);
    }
  }
  saveNow();
}

// ----------------------------------------------------------------- AI settings
function getAI() {
  const s = db.settings || {};
  const provider = PROVIDERS[s.provider] ? s.provider : (PROVIDERS[process.env.AI_PROVIDER] ? process.env.AI_PROVIDER : 'gemini');
  const p = PROVIDERS[provider];
  const useEnv = !s.provider;
  const baseUrl = String(s.baseUrl || (useEnv && process.env.AI_BASE_URL) || p.baseUrl || '').replace(/\/+$/, '');
  const model = s.model || (useEnv && process.env.AI_MODEL) || p.model || '';
  const keySource = s.apiKey ? 'admin' : (process.env.AI_API_KEY ? 'env' : 'none');
  return {
    provider, kind: p.kind, baseUrl, model,
    apiKey: s.apiKey || process.env.AI_API_KEY || '',
    keySource,
    systemPrompt: s.systemPrompt || DEFAULT_SYSTEM,
    maxTokens: s.maxTokens || 4096,
    maxHistory: s.maxHistory || 30,
    rateLimit: s.rateLimit || 20,
    allowRegistration: s.allowRegistration !== false,
  };
}

// ---------------------------------------------------------- AI streaming core
async function* readSSE(res) {
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buf = '';
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    let m;
    while ((m = /\r?\n\r?\n/.exec(buf))) {
      const raw = buf.slice(0, m.index);
      buf = buf.slice(m.index + m[0].length);
      const data = raw.split(/\r?\n/).filter((l) => l.startsWith('data:')).map((l) => l.slice(5).trimStart()).join('\n');
      if (data) yield data;
    }
  }
  const tail = buf.split(/\r?\n/).filter((l) => l.startsWith('data:')).map((l) => l.slice(5).trimStart()).join('\n');
  if (tail) yield tail;
}

function mapUpstream(status, text, key) {
  let detail = text || '';
  try {
    const j = JSON.parse(text);
    detail = (j.error && (j.error.message || j.error)) || (j[0] && j[0].error && j[0].error.message) || j.message || text;
  } catch (e) { /* keep raw */ }
  detail = String(typeof detail === 'string' ? detail : JSON.stringify(detail));
  if (key) detail = detail.split(key).join('***');
  let code = 'ai_error';
  if (status === 401 || status === 403) code = 'ai_auth';
  else if (status === 404) code = 'ai_not_found';
  else if (status === 429) code = 'ai_rate';
  else if (status === 400) code = 'ai_bad_request';
  else if (status >= 500) code = 'ai_down';
  return new AIError(code, `[${status}] ${detail.slice(0, 300)}`);
}

/** items: [{role:'user'|'assistant', text, images:[{mime,data}]}] */
async function* streamCompletion(ai, items, signal) {
  let url; let headers; let body;
  if (ai.kind === 'anthropic') {
    url = ai.baseUrl + '/v1/messages';
    headers = { 'content-type': 'application/json', 'x-api-key': ai.apiKey, 'anthropic-version': '2023-06-01' };
    body = {
      model: ai.model, max_tokens: ai.maxTokens, stream: true, system: ai.systemPrompt,
      messages: items.map((it) => {
        const blocks = [];
        for (const im of it.images || []) blocks.push({ type: 'image', source: { type: 'base64', media_type: im.mime, data: im.data } });
        blocks.push({ type: 'text', text: it.text || ' ' });
        return { role: it.role, content: blocks };
      }),
    };
  } else {
    url = ai.baseUrl + '/chat/completions';
    headers = { 'content-type': 'application/json', authorization: 'Bearer ' + ai.apiKey };
    body = {
      model: ai.model, stream: true,
      messages: [{ role: 'system', content: ai.systemPrompt }].concat(items.map((it) => {
        if (!it.images || !it.images.length) return { role: it.role, content: it.text || ' ' };
        const parts = [{ type: 'text', text: it.text || ' ' }];
        for (const im of it.images) parts.push({ type: 'image_url', image_url: { url: `data:${im.mime};base64,${im.data}` } });
        return { role: it.role, content: parts };
      })),
    };
  }
  let res;
  try {
    res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body), signal });
  } catch (e) {
    if (signal && signal.aborted) throw e;
    throw new AIError('ai_network', (e.cause && e.cause.message) || e.message);
  }
  if (!res.ok) throw mapUpstream(res.status, await res.text().catch(() => ''), ai.apiKey);

  for await (const data of readSSE(res)) {
    if (data === '[DONE]') break;
    let j; try { j = JSON.parse(data); } catch (e) { continue; }
    if (ai.kind === 'anthropic') {
      if (j.type === 'content_block_delta' && j.delta && j.delta.type === 'text_delta' && j.delta.text) yield j.delta.text;
      else if (j.type === 'error') throw new AIError('ai_error', (j.error && j.error.message) || 'error');
    } else {
      if (j.error) throw new AIError('ai_error', typeof j.error === 'string' ? j.error : (j.error.message || 'error'));
      const d = j.choices && j.choices[0] && j.choices[0].delta;
      if (d && typeof d.content === 'string' && d.content) yield d.content;
    }
  }
}

function messageText(m) {
  let t = m.content || '';
  for (const a of m.attachments || []) {
    if (a.kind === 'text') t += `\n\n[Attached file: ${a.name}]\n\`\`\`\n${a.text}\n\`\`\``;
  }
  return t;
}
function buildHistory(chat, ai) {
  let msgs = chat.messages.slice(-ai.maxHistory);
  let total = msgs.reduce((n, m) => n + messageText(m).length, 0);
  while (msgs.length > 1 && total > 150000) { total -= messageText(msgs[0]).length; msgs.shift(); }
  while (msgs.length && msgs[0].role !== 'user') msgs.shift();
  const items = [];
  msgs.forEach((m, i) => {
    const isLast = i === msgs.length - 1;
    let text = messageText(m);
    const images = [];
    for (const a of m.attachments || []) {
      if (a.kind !== 'image') continue;
      if (isLast && a.data) images.push({ mime: a.mime, data: a.data });
      else text += `\n[Attached image: ${a.name}]`;
    }
    const prev = items[items.length - 1];
    if (prev && prev.role === m.role) { prev.text += '\n\n' + text; prev.images.push(...images); }
    else items.push({ role: m.role, text, images });
  });
  return items;
}

// -------------------------------------------------------------- chat handlers
const IMG_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp', 'image/gif']);
function cleanAttachments(list) {
  if (!Array.isArray(list)) return [];
  if (list.length > 4) throw new HttpError(400, 'too_many_files');
  return list.map((a) => {
    const name = String((a && a.name) || 'file').slice(0, 120);
    if (a && a.kind === 'image') {
      if (!IMG_TYPES.has(a.mime) || typeof a.data !== 'string' || a.data.length > 3 * 1024 * 1024 || !/^[A-Za-z0-9+/=]+$/.test(a.data)) throw new HttpError(400, 'bad_image');
      return { kind: 'image', name, mime: a.mime, data: a.data };
    }
    if (a && a.kind === 'text') {
      if (typeof a.text !== 'string' || a.text.length > 200000) throw new HttpError(400, 'bad_file');
      return { kind: 'text', name, text: a.text };
    }
    throw new HttpError(400, 'bad_file');
  });
}
function chatSummary(c) { return { id: c.id, title: c.title, updatedAt: c.updatedAt }; }
function chatFull(c) {
  return {
    id: c.id, title: c.title, updatedAt: c.updatedAt,
    messages: c.messages.map((m) => ({
      id: m.id, role: m.role, content: m.content, ts: m.ts,
      attachments: (m.attachments || []).map((a) => ({ kind: a.kind, name: a.name })),
    })),
  };
}
function userChat(user, id) {
  const c = db.chats[id];
  if (!c || c.userId !== user.id) throw new HttpError(404, 'not_found');
  return c;
}

async function handleMessage(req, res, user, chat) {
  const body = await readJson(req, 6 * 1024 * 1024);
  const ai = getAI();
  if (!ai.apiKey) throw new HttpError(503, 'ai_not_configured');
  if (!ai.baseUrl || !ai.model) throw new HttpError(503, 'ai_not_configured');
  if (!hit('chat:' + user.id, ai.rateLimit, 60000)) throw new HttpError(429, 'rate_limited');
  if (chat.messages.length > 400) throw new HttpError(400, 'chat_too_long');

  if (body.regenerate) {
    while (chat.messages.length && chat.messages[chat.messages.length - 1].role === 'assistant') chat.messages.pop();
    if (!chat.messages.length) throw new HttpError(400, 'nothing_to_regenerate');
  } else {
    const content = typeof body.content === 'string' ? body.content.trim() : '';
    if (content.length > 20000) throw new HttpError(400, 'message_too_long');
    const attachments = cleanAttachments(body.attachments);
    if (!content && !attachments.length) throw new HttpError(400, 'empty');
    for (const m of chat.messages) for (const a of m.attachments || []) if (a.kind === 'image') delete a.data; // keep only newest images
    chat.messages.push({ id: uid(), role: 'user', content, attachments, ts: now() });
    if (!chat.title) {
      const t = (content || (attachments[0] && attachments[0].name) || 'Chat').replace(/\s+/g, ' ');
      chat.title = t.length > 48 ? t.slice(0, 48) + '…' : t;
    }
  }
  chat.updatedAt = now();
  saveSoon();
  const k = dayKey();
  db.stats[k] = db.stats[k] || { requests: 0 };
  db.stats[k].requests++;

  res.writeHead(200, {
    'Content-Type': 'text/event-stream; charset=utf-8', 'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive', 'X-Accel-Buffering': 'no',
  });
  const send = (o) => { if (!res.destroyed && !res.writableEnded) res.write('data: ' + JSON.stringify(o) + '\n\n'); };
  const ctrl = new AbortController();
  let finished = false;
  res.on('close', () => { if (!finished) ctrl.abort(); });
  const ping = setInterval(() => { if (!res.destroyed) res.write(': ping\n\n'); }, 15000);

  let acc = '';
  try {
    for await (const d of streamCompletion(ai, buildHistory(chat, ai), ctrl.signal)) {
      acc += d; send({ type: 'delta', text: d });
    }
    if (!acc.trim()) throw new AIError('ai_empty', '');
  } catch (e) {
    if (!ctrl.signal.aborted) {
      if (!(e instanceof AIError)) console.error('AI error:', e.message);
      send({ type: 'error', code: e.code && String(e.code).startsWith('ai_') ? e.code : 'ai_error', detail: e instanceof AIError ? e.detail : '' });
    }
  }
  clearInterval(ping);
  let msgId = null;
  if (acc.trim()) {
    msgId = uid();
    chat.messages.push({ id: msgId, role: 'assistant', content: acc, ts: now() });
    chat.updatedAt = now();
    saveSoon();
  }
  finished = true;
  send({ type: 'done', id: msgId, title: chat.title, updatedAt: chat.updatedAt });
  if (!res.writableEnded) res.end();
}

// ------------------------------------------------------------------- routing
async function api(req, res, url) {
  const p = url.pathname.replace(/\/+$/, '');
  const method = req.method;
  let m;

  if (method === 'GET' && p === '/api/config') {
    return json(res, 200, { appName: 'Aura Needs', tagline: 'Your World, Your AI.', allowRegistration: getAI().allowRegistration });
  }

  // ----- auth
  if (method === 'POST' && (p === '/api/auth/register' || p === '/api/auth/login')) {
    const ip = clientIp(req);
    if (!hit('auth:' + ip, 20, 15 * 60000)) throw new HttpError(429, 'too_many_attempts');
    const b = await readJson(req);
    const email = String(b.email || '').trim().toLowerCase();
    const password = String(b.password || '');
    if (p.endsWith('/register')) {
      if (!getAI().allowRegistration) throw new HttpError(403, 'registration_closed');
      const name = String(b.name || '').trim().slice(0, 50);
      if (!name) throw new HttpError(400, 'name_required');
      if (!EMAIL_RE.test(email) || email.length > 120) throw new HttpError(400, 'bad_email');
      if (password.length < 6 || password.length > 100) throw new HttpError(400, 'weak_password');
      if (Object.values(db.users).some((u) => u.email === email)) throw new HttpError(409, 'email_taken');
      const salt = crypto.randomBytes(16).toString('hex');
      const u = { id: uid(), name, email, salt, hash: await hashPassword(password, salt), role: 'user', banned: false, createdAt: now(), lastLogin: now() };
      db.users[u.id] = u; saveSoon();
      return json(res, 200, { token: signToken({ uid: u.id, exp: now() + 30 * 86400000 }), user: publicUser(u) });
    }
    const u = Object.values(db.users).find((x) => x.email === email);
    if (!u || !(await verifyPassword(password, u))) throw new HttpError(401, 'bad_credentials');
    if (u.banned) throw new HttpError(403, 'banned');
    u.lastLogin = now(); saveSoon();
    return json(res, 200, { token: signToken({ uid: u.id, exp: now() + 30 * 86400000 }), user: publicUser(u) });
  }
  if (method === 'GET' && p === '/api/me') return json(res, 200, { user: publicUser(authUser(req)) });

  // ----- chats
  if (p === '/api/chats') {
    const user = authUser(req);
    if (method === 'GET') {
      const list = Object.values(db.chats).filter((c) => c.userId === user.id).sort((a, b) => b.updatedAt - a.updatedAt).map(chatSummary);
      return json(res, 200, { chats: list });
    }
    if (method === 'POST') {
      const count = Object.values(db.chats).filter((c) => c.userId === user.id).length;
      if (count >= 500) throw new HttpError(400, 'too_many_chats');
      const c = { id: uid(), userId: user.id, title: '', createdAt: now(), updatedAt: now(), messages: [] };
      db.chats[c.id] = c; saveSoon();
      return json(res, 200, { chat: chatSummary(c) });
    }
    if (method === 'DELETE') {
      for (const c of Object.values(db.chats)) if (c.userId === user.id) delete db.chats[c.id];
      saveSoon();
      return json(res, 200, { ok: true });
    }
  }
  if ((m = p.match(/^\/api\/chats\/([\w-]+)$/))) {
    const user = authUser(req);
    const chat = userChat(user, m[1]);
    if (method === 'GET') return json(res, 200, { chat: chatFull(chat) });
    if (method === 'PATCH') {
      const b = await readJson(req);
      const t = String(b.title || '').trim().slice(0, 80);
      if (!t) throw new HttpError(400, 'empty');
      chat.title = t; saveSoon();
      return json(res, 200, { chat: chatSummary(chat) });
    }
    if (method === 'DELETE') { delete db.chats[chat.id]; saveSoon(); return json(res, 200, { ok: true }); }
  }
  if (method === 'POST' && (m = p.match(/^\/api\/chats\/([\w-]+)\/message$/))) {
    const user = authUser(req);
    return handleMessage(req, res, user, userChat(user, m[1]));
  }

  // ----- admin
  if (p.startsWith('/api/admin/')) {
    const admin = requireAdmin(req);

    if (method === 'GET' && p === '/api/admin/stats') {
      const ai = getAI();
      const users = Object.values(db.users);
      let messages = 0; for (const c of Object.values(db.chats)) messages += c.messages.length;
      let total = 0; for (const v of Object.values(db.stats)) total += v.requests || 0;
      return json(res, 200, {
        users: users.length, admins: users.filter((u) => u.role === 'admin').length, banned: users.filter((u) => u.banned).length,
        chats: Object.keys(db.chats).length, messages,
        requestsToday: (db.stats[dayKey()] || {}).requests || 0, requestsTotal: total,
        aiConfigured: !!(ai.apiKey && ai.baseUrl && ai.model), provider: PROVIDERS[ai.provider].label, model: ai.model, keySource: ai.keySource,
      });
    }
    if (p === '/api/admin/settings') {
      if (method === 'GET') {
        const ai = getAI();
        return json(res, 200, {
          settings: {
            provider: ai.provider, model: ai.model, baseUrl: ai.baseUrl, systemPrompt: ai.systemPrompt, maxTokens: ai.maxTokens,
            maxHistory: ai.maxHistory, rateLimit: ai.rateLimit, allowRegistration: ai.allowRegistration,
          },
          apiKey: { set: !!ai.apiKey, source: ai.keySource, hint: ai.apiKey ? '••••' + ai.apiKey.slice(-4) : '' },
          providers: Object.fromEntries(Object.entries(PROVIDERS).map(([k, v]) => [k, { label: v.label, baseUrl: v.baseUrl, model: v.model }])),
        });
      }
      if (method === 'PUT') {
        const b = await readJson(req);
        const s = db.settings;
        if (b.provider !== undefined) {
          if (!PROVIDERS[b.provider]) throw new HttpError(400, 'bad_provider');
          s.provider = b.provider;
        }
        const setStr = (key, max, trim = true) => {
          if (b[key] === undefined) return;
          const v = String(b[key]); const t = trim ? v.trim() : v;
          if (t.length > max) throw new HttpError(400, 'too_long');
          if (t) s[key] = t; else delete s[key];
        };
        setStr('model', 120); setStr('systemPrompt', 8000, false);
        if (b.baseUrl !== undefined) {
          const u = String(b.baseUrl).trim();
          if (u && !/^https:\/\/[^\s]+$/.test(u) && !/^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?(\/[^\s]*)?$/.test(u)) throw new HttpError(400, 'bad_url');
          if (u) s.baseUrl = u; else delete s.baseUrl;
        }
        if (typeof b.apiKey === 'string' && b.apiKey.trim()) {
          if (b.apiKey.trim().length < 8 || /\s/.test(b.apiKey.trim())) throw new HttpError(400, 'bad_key');
          s.apiKey = b.apiKey.trim();
        }
        if (b.clearApiKey) delete s.apiKey;
        const setInt = (key, lo, hi) => {
          if (b[key] === undefined) return;
          const n = Math.round(Number(b[key]));
          if (!Number.isFinite(n) || n < lo || n > hi) throw new HttpError(400, 'bad_number');
          s[key] = n;
        };
        setInt('maxTokens', 256, 32000); setInt('maxHistory', 2, 100); setInt('rateLimit', 1, 300);
        if (b.allowRegistration !== undefined) s.allowRegistration = !!b.allowRegistration;
        saveSoon();
        return json(res, 200, { ok: true });
      }
    }
    if (method === 'POST' && p === '/api/admin/test') {
      const ai = getAI();
      if (!ai.apiKey) return json(res, 200, { ok: false, code: 'ai_not_configured', detail: '' });
      try {
        let out = '';
        const items = [{ role: 'user', text: 'Reply with just the word: OK', images: [] }];
        for await (const d of streamCompletion({ ...ai, maxTokens: 64, systemPrompt: 'You are a connection test.' }, items, AbortSignal.timeout(30000))) {
          out += d; if (out.length > 80) break;
        }
        return json(res, 200, { ok: true, reply: out.trim().slice(0, 80), model: ai.model });
      } catch (e) {
        return json(res, 200, { ok: false, code: e.code || 'ai_error', detail: e.detail || e.message });
      }
    }
    if (method === 'GET' && p === '/api/admin/users') {
      const counts = {};
      for (const c of Object.values(db.chats)) counts[c.userId] = (counts[c.userId] || 0) + 1;
      const list = Object.values(db.users).sort((a, b) => b.createdAt - a.createdAt).map((u) => ({
        id: u.id, name: u.name, email: u.email, role: u.role, banned: !!u.banned, createdAt: u.createdAt, lastLogin: u.lastLogin, chats: counts[u.id] || 0,
      }));
      return json(res, 200, { users: list, me: admin.id });
    }
    if ((m = p.match(/^\/api\/admin\/users\/([\w-]+)$/))) {
      const u = db.users[m[1]];
      if (!u) throw new HttpError(404, 'not_found');
      if (u.id === admin.id) throw new HttpError(400, 'cannot_modify_self');
      if (method === 'PATCH') {
        const b = await readJson(req);
        if (b.banned !== undefined) u.banned = !!b.banned;
        if (b.role !== undefined) {
          if (b.role !== 'admin' && b.role !== 'user') throw new HttpError(400, 'bad_role');
          u.role = b.role;
        }
        saveSoon();
        return json(res, 200, { ok: true });
      }
      if (method === 'DELETE') {
        for (const c of Object.values(db.chats)) if (c.userId === u.id) delete db.chats[c.id];
        delete db.users[u.id]; saveSoon();
        return json(res, 200, { ok: true });
      }
    }
  }
  throw new HttpError(404, 'not_found');
}

// -------------------------------------------------------------- embedded website (single-file build)
const INDEX_HTML = Buffer.from('', 'base64');
const FAVICON = Buffer.from('', 'base64');
function serveStatic(req, res, url) {
  if (url.pathname === '/favicon.svg') {
    res.writeHead(200, { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public, max-age=86400' });
    return res.end(req.method === 'HEAD' ? undefined : FAVICON);
  }
  if (/\.[a-z0-9]+$/i.test(url.pathname)) { res.writeHead(404, { 'Content-Type': 'text/plain' }); return res.end('Not found'); }
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' });
  res.end(req.method === 'HEAD' ? undefined : INDEX_HTML);
}

const SEC_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'same-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  'Content-Security-Policy': "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
};

const server = http.createServer(async (req, res) => {
  for (const [k, v] of Object.entries(SEC_HEADERS)) res.setHeader(k, v);
  try {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname === '/healthz') { res.writeHead(200, { 'Content-Type': 'text/plain' }); return res.end('ok'); }
    if (url.pathname.startsWith('/api/')) return await api(req, res, url);
    if (req.method !== 'GET' && req.method !== 'HEAD') { res.writeHead(405); return res.end(); }
    return serveStatic(req, res, url);
  } catch (e) {
    if (res.headersSent) { try { res.end(); } catch (x) { /* ignore */ } return; }
    if (e instanceof HttpError) return json(res, e.status, { error: e.code });
    console.error('Server error:', e);
    return json(res, 500, { error: 'server_error' });
  }
});
server.requestTimeout = 0;
server.headersTimeout = 30000;

ensureAdmin().then(() => {
  server.listen(PORT, () => {
    const ai = getAI();
    console.log(`\n  Aura Needs is running → http://localhost:${PORT}`);
    console.log(`  AI provider: ${PROVIDERS[ai.provider].label} | model: ${ai.model} | API key: ${ai.apiKey ? 'set (' + ai.keySource + ')' : 'NOT SET'}\n`);
  });
});
